class InputController {
  constructor() {
    this.keys = {
      left: false,
      right: false,
      fire: false
    };
    this.gamepadIndex = -1;
    this.setupKeyboardListeners();
    this.setupGamepadListeners();
  }

  setupKeyboardListeners() {
    document.addEventListener('keydown', (event) => {
      switch(event.code) {
        case 'ArrowLeft':
        case 'KeyA':
          this.keys.left = true;
          break;
        case 'ArrowRight':
        case 'KeyD':
          this.keys.right = true;
          break;
        case 'Space':
        case 'Enter':
          this.keys.fire = true;
          break;
      }
    });

    document.addEventListener('keyup', (event) => {
      switch(event.code) {
        case 'ArrowLeft':
        case 'KeyA':
          this.keys.left = false;
          break;
        case 'ArrowRight':
        case 'KeyD':
          this.keys.right = false;
          break;
        case 'Space':
        case 'Enter':
          this.keys.fire = false;
          break;
      }
    });
  }

  setupGamepadListeners() {
    window.addEventListener('gamepadconnected', (e) => {
      console.log('Gamepad connected at index %d: %s. %d buttons, %d axes.',
        e.gamepad.index, e.gamepad.id,
        e.gamepad.buttons.length, e.gamepad.axes.length);
      this.gamepadIndex = e.gamepad.index;
    });

    window.addEventListener('gamepaddisconnected', (e) => {
      console.log('Gamepad disconnected at index %d: %s.', e.gamepad.index, e.gamepad.id);
      if (this.gamepadIndex === e.gamepad.index) {
        this.gamepadIndex = -1;
      }
    });
  }

  getHorizontalInput() {
    let horizontalInput = 0;
    if (this.keys.left) horizontalInput -= 1;
    if (this.keys.right) horizontalInput += 1;

    if (this.gamepadIndex !== -1) {
      const gamepad = navigator.getGamepads()[this.gamepadIndex];
      if (gamepad) {
        const leftStickX = gamepad.axes[0] || 0;
        if (Math.abs(leftStickX) > 0.1) {
          horizontalInput = leftStickX;
        } else {
          const dpadLeft = gamepad.buttons[14]?.pressed ? -1 : 0;
          const dpadRight = gamepad.buttons[15]?.pressed ? 1 : 0;
          horizontalInput = dpadLeft + dpadRight;
        }
      }
    }

    return horizontalInput;
  }

  getFireInput() {
    if (this.keys.fire) return true;
    if (this.gamepadIndex !== -1) {
      const gamepad = navigator.getGamepads()[this.gamepadIndex];
      if (gamepad) {
        const fireButton = gamepad.buttons[0] || gamepad.buttons[9];
        if (fireButton && fireButton.pressed) return true;
      }
    }
    return false;
  }

  resetFire() {
    this.keys.fire = false;
  }
}

export { InputController };
