class ObjectPool {
  constructor(createFn, resetFn, initialSize = 10) {
    this.createFn = createFn;
    this.resetFn = resetFn;
    this.pool = [];
    this.availableItems = [];

    for (let i = 0; i < initialSize; i++) {
      const item = this.createFn();
      this.pool.push(item);
      this.availableItems.push(item);
    }
  }

  acquire() {
    if (this.availableItems.length > 0) {
      const item = this.availableItems.pop();
      return item;
    } else {
      const item = this.createFn();
      this.pool.push(item);
      return item;
    }
  }

  release(item) {
    if (!this.pool.includes(item)) {
      this.pool.push(item);
    }
    this.resetFn(item);
    this.availableItems.push(item);
  }

  getAllItems() {
    return this.pool;
  }

  getAvailableCount() {
    return this.availableItems.length;
  }
}

export { ObjectPool };
