import * as THREE from 'three';
import { ObjectPool } from '../pooling/ObjectPool.js';

class ParticleManager {
  constructor(maxParticles = 500) {
    this.maxParticles = maxParticles;
    this.particles = [];
    this.activeParticles = [];
    this.geometry = new THREE.SphereGeometry(0.1, 8, 8);
    this.materialBase = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 1, depthWrite: false });

    for (let i = 0; i < maxParticles; i++) {
      const mesh = new THREE.Mesh(this.geometry, this.materialBase.clone());
      mesh.visible = false;
      this.particles.push({
        mesh: mesh,
        velocity: new THREE.Vector3(),
        life: 0,
        maxLife: 1,
        active: false
      });
    }

    this.scene = null;
  }

  setScene(scene) {
    this.scene = scene;
    for (const p of this.particles) {
      this.scene.add(p.mesh);
    }
  }

  spawnBurst(position, color, count) {
    let spawnedCount = 0;
    for (const p of this.particles) {
      if (!p.active && spawnedCount < count) {
        p.active = true;
        p.mesh.position.copy(position);
        p.mesh.material.color.set(color);
        p.mesh.material.opacity = 1;

        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(2 * Math.random() - 1);
        const speed = 0.5 + Math.random() * 1.5;

        p.velocity.x = speed * Math.sin(phi) * Math.cos(theta);
        p.velocity.y = speed * Math.sin(phi) * Math.sin(theta);
        p.velocity.z = speed * Math.cos(phi);

        p.life = 0;
        p.maxLife = 0.5 + Math.random() * 0.5;

        this.activeParticles.push(p);
        spawnedCount++;
      }
    }
  }

  update(deltaTime) {
    for (let i = this.activeParticles.length - 1; i >= 0; i--) {
      const p = this.activeParticles[i];
      p.life += deltaTime;

      if (p.life >= p.maxLife) {
        p.active = false;
        p.mesh.visible = false;
        this.activeParticles.splice(i, 1);
      } else {
        const lifeRatio = p.life / p.maxLife;
        p.mesh.position.addScaledVector(p.velocity, deltaTime);
        p.velocity.y -= 9.8 * deltaTime * 0.5;
        p.mesh.material.opacity = 1 - lifeRatio;
      }
    }

    if (this.activeParticles.length > this.maxParticles) {
      const overflow = this.activeParticles.length - this.maxParticles;
      for (let i = 0; i < overflow && i < this.activeParticles.length; i++) {
        const p = this.activeParticles.shift();
        p.active = false;
        p.mesh.visible = false;
      }
    }
  }

  dispose() {
    for (const p of this.particles) {
      if (this.scene && p.mesh.parent) {
        this.scene.remove(p.mesh);
      }
      p.mesh.geometry.dispose();
      p.mesh.material.dispose();
    }
    this.geometry.dispose();
    this.materialBase.dispose();
  }
}

export { ParticleManager };
```

