class HitStop {
  constructor() {
    this.isActive = false;
    this.framesRemaining = 0;
    this.timescale = 1.0;
  }

  trigger(frames) {
    this.isActive = true;
    this.framesRemaining = frames;
    this.timescale = 0.0;
  }

  update(deltaTime) {
    if (this.isActive) {
      this.framesRemaining--;
      if (this.framesRemaining <= 0) {
        this.isActive = false;
        this.timescale = 1.0;
      } else {
        this.timescale = 0.0;
      }
    } else {
      this.timescale = 1.0;
    }
    return this.timescale;
  }

  isActiveStop() {
    return this.isActive;
  }
}

