import * as THREE from 'three';

class ShockwaveRing {
  constructor() {
    this.rings = [];
    this.geometry = new THREE.RingGeometry(1, 1.2, 32);
    this.materialBase = new THREE.MeshBasicMaterial({ color: 0x00ffff, transparent: true, opacity: 0.8, side: THREE.DoubleSide, depthWrite: false });
  }

  spawnShockwave(position, radius, color) {
    const mesh = new THREE.Mesh(this.geometry, this.materialBase.clone());
    mesh.material.color.set(color);
    mesh.position.copy(position);
    mesh.rotation.x = -Math.PI / 2;

    this.rings.push({
      mesh: mesh,
      radius: radius || 1,
      maxRadius: 5 + Math.random() * 3,
      speed: 2 + Math.random() * 2,
      opacity: 0.8,
      life: 0,
      maxLife: 1.0
    });

    return mesh;
  }

  update(deltaTime, scene) {
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const ring = this.rings[i];
      ring.life += deltaTime;

      if (ring.life >= ring.maxLife) {
        scene.remove(ring.mesh);
        ring.mesh.geometry.dispose();
        ring.mesh.material.dispose();
        this.rings.splice(i, 1);
      } else {
        const lifeRatio = ring.life / ring.maxLife;
        const currentRadius = ring.radius + (ring.maxRadius - ring.radius) * lifeRatio;
        ring.mesh.scale.set(currentRadius, currentRadius, 1);
        ring.mesh.material.opacity = 0.8 * (1 - lifeRatio);
      }
    }
  }

  dispose() {
    for (const ring of this.rings) {
      ring.mesh.geometry.dispose();
      ring.mesh.material.dispose();
    }
    this.geometry.dispose();
    this.materialBase.dispose();
  }
}

export { ShockwaveRing };
