class ScoreText {
  constructor(containerId = 'floating-texts-container') {
    this.container = document.getElementById(containerId);
    if (!this.container) {
      console.error('Floating text container not found:', containerId);
      this.container = document.createElement('div');
      this.container.id = containerId;
      document.body.appendChild(this.container);
    }
    this.texts = [];
  }

  showFloatingText(worldPosition, text, color) {
    const el = document.createElement('div');
    el.className = 'floating-score-text';
    el.style.color = color || '#00ffff';
    el.textContent = text;
    this.container.appendChild(el);

    this.texts.push({
      element: el,
      worldPosition: worldPosition.clone(),
      life: 1.0,
      maxLife: 1.0
    });
  }

  update(deltaTime, camera, renderer) {
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const t = this.texts[i];
      t.life -= deltaTime;

      if (t.life <= 0) {
        if (t.element.parentNode) {
          t.element.parentNode.removeChild(t.element);
        }
        this.texts.splice(i, 1);
        continue;
      }

      const tempVec = t.worldPosition.clone();
      tempVec.project(camera);

      const x = (tempVec.x * .5 + .5) * renderer.domElement.clientWidth;
      const y = (-tempVec.y * .5 + .5) * renderer.domElement.clientHeight;

      if (tempVec.z > 1 || tempVec.z < -1) {
        if (t.element.parentNode) {
          t.element.parentNode.removeChild(t.element);
        }
        this.texts.splice(i, 1);
        continue;
      }

      t.element.style.transform = `translate(${x}px, ${y}px) translate(-50%, -50%)`;
      t.element.style.opacity = t.life;
    }
  }

  clearAll() {
    for (const t of this.texts) {
      if (t.element.parentNode) {
        t.element.parentNode.removeChild(t.element);
      }
    }
    this.texts = [];
  }
}

export { ScoreText };
