class CameraShake {
  constructor() {
    this.intensity = 0;
    this.decayFactor = 0.95;
    this.isShaking = false;
  }

  shake(intensity, duration) {
    this.intensity = intensity;
    this.isShaking = true;
    this.shakeDuration = duration || 0.5;
    this.elapsedShakeTime = 0;
  }

  update(deltaTime, camera) {
    if (!this.isShaking) return;

    this.elapsedShakeTime += deltaTime;
    if (this.elapsedShakeTime >= this.shakeDuration) {
      this.isShaking = false;
      this.intensity = 0;
      camera.position.x = 0;
      camera.position.y = 0;
      return;
    }

    const currentIntensity = this.intensity * (1 - this.elapsedShakeTime / this.shakeDuration);
    if (currentIntensity <= 0) {
      this.isShaking = false;
      this.intensity = 0;
      camera.position.x = 0;
      camera.position.y = 0;
      return;
    }

    const offsetX = (Math.random() - 0.5) * currentIntensity;
    const offsetY = (Math.random() - 0.5) * currentIntensity;

    camera.position.x += offsetX;
    camera.position.y += offsetY;
  }

  reset(camera) {
    this.isShaking = false;
    this.intensity = 0;
    camera.position.x = 0;
    camera.position.y = 0;
  }
}

