import * as THREE from 'three';

class MotionTrail {
  constructor(maxPoints = 20) {
    this.maxPoints = maxPoints;
    this.points = [];
    this.geometry = new THREE.BufferGeometry();
    const positions = new Float32Array(maxPoints * 3);
    this.geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    this.material = new THREE.LineBasicMaterial({ color: 0x00ffff, transparent: true, opacity: 0.5, depthWrite: false });
    this.line = new THREE.Line(this.geometry, this.material);
    this.line.visible = false;
  }

  addPoint(position, color) {
    if (this.points.length >= this.maxPoints) {
      this.points.shift();
    }
    this.points.push({
      position: position.clone(),
      color: color || new THREE.Color(0x00ffff),
      opacity: 1.0
    });

    this.line.visible = true;
    this.updateGeometry();
  }

  updateGeometry() {
    const positions = this.geometry.attributes.position.array;
    for (let i = 0; i < this.points.length; i++) {
      const p = this.points[i];
      positions[i * 3] = p.position.x;
      positions[i * 3 + 1] = p.position.y;
      positions[i * 3 + 2] = p.position.z;
    }
    const lastPos = this.points.length > 0 ? this.points[this.points.length - 1].position : new THREE.Vector3();
    for (let i = this.points.length; i < this.maxPoints; i++) {
      positions[i * 3] = lastPos.x;
      positions[i * 3 + 1] = lastPos.y;
      positions[i * 3 + 2] = lastPos.z;
    }
    this.geometry.attributes.position.needsUpdate = true;

    const colors = new Float32Array(this.maxPoints * 3);
    for (let i = 0; i < this.points.length; i++) {
      const p = this.points[i];
      const fadeFactor = i / this.points.length;
      const color = p.color.clone();
      color.multiplyScalar(fadeFactor);
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }
    for (let i = this.points.length; i < this.maxPoints; i++) {
      colors[i * 3] = 0;
      colors[i * 3 + 1] = 0;
      colors[i * 3 + 2] = 0;
    }
    this.geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    this.material.vertexColors = true;
  }

  updateAndRender() {
    if (this.points.length > 0) {
      const lastPoint = this.points[this.points.length - 1];
      lastPoint.opacity -= 0.05;
      if (lastPoint.opacity <= 0) {
        this.points.pop();
        if (this.points.length === 0) {
          this.line.visible = false;
        } else {
          this.updateGeometry();
        }
      } else {
        this.updateGeometry();
      }
    }
  }

  dispose() {
    this.geometry.dispose();
    this.material.dispose();
  }
}

export { MotionTrail };
